import pathlib,json,sys,numpy as np,trimesh,igl
R=pathlib.Path(__file__).resolve().parents[1];id=int(sys.argv[1]);r=json.loads((R/f'results/{id}/report.json').read_text());s=np.load(R/f'data/source/{id}.npz');a=np.load(R/f'results/{id}/quad.npz');v=a['vertices'];f=a['quads'].reshape(-1,3,4)[:,:,0];sv=(s['vertices']-a['source_center'])/a['source_scale'];sf=s['facets'];np.random.seed(id);t=trimesh.Trimesh(sv,sf,process=False);p=t.sample(12000);d=np.sqrt(np.maximum(igl.point_mesh_squared_distance(p,v,f)[0],0));diag=np.linalg.norm(np.ptp(sv,axis=0));threshold=.002*diag;mask=d>threshold;w=igl.fast_winding_number(v,f,p[mask]);review={'threshold_percent_diagonal':.2,'source_sample_count':12000,'samples_above_threshold':int(mask.sum()),'fraction_above_threshold_inside_repaired_solid':float(np.mean(np.abs(w)>.5)),'interpretation':'Interior source surfaces can be removed when overlapping volumes are consolidated. This is not an exterior-only accuracy certificate.'};(R/f'results/{id}/deviation_review.json').write_text(json.dumps(review,indent=2));print(review)
